import { useState } from 'react';
import { JxChip, JxTagInput } from '@jinx-ui/react';

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  value?: string[];
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
};

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  value,
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [uncontrolled, setUncontrolled] = useState<string[]>(defaultValue);
  const tags = value ?? uncontrolled;

  const commit = (next: string[]) => {
    if (value === undefined) setUncontrolled(next);
    onChange?.(next);
  };

  const handleValueChange = (next: string[]) => {
    const cleaned: string[] = [];
    for (const raw of next) {
      const tag = raw.trim();
      if (tag && !cleaned.some((item) => item.toLowerCase() === tag.toLowerCase())) {
        cleaned.push(tag);
      }
    }
    commit(cleaned);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
      <span
        style={{
          color: 'var(--jx-text)',
          font: 'var(--jx-font-ui)',
          fontWeight: 600,
        }}
      >
        {label}
      </span>

      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={handleValueChange}
      />

      <div
        aria-live="polite"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', minHeight: '28px' }}
      >
        {tags.length === 0 ? (
          <span style={{ color: 'var(--jx-text-2)', font: 'var(--jx-font-ui)' }}>
            Пока ни одного тега. Наберите слово и нажмите Enter, чтобы добавить.
          </span>
        ) : (
          tags.map((tag) => (
            <JxChip
              key={tag}
              removable
              onRemove={() => commit(tags.filter((item) => item !== tag))}
            >
              {tag}
            </JxChip>
          ))
        )}
      </div>
    </div>
  );
}

